document.addEventListener('click',e=>{let b=e.target.closest('[data-fav],[data-delete],[data-copy-item],[data-download],[data-cloud-save],[data-cloud-remove],[data-cloud-import]');if(!b)return;if(b.dataset.cloudImport){const o=cloudItems.find(x=>x.id===b.dataset.cloudImport);if(o){if(items.some(x=>x.id===o.id))return toast('Already saved locally.','err');items.unshift({...o,meta:{},fav:!!o.fav});save('items',items);render();toast('Restored to this browser.','ok')}return}if(b.dataset.cloudRemove){if(!confirm('Delete the cloud copy of this project?'))return;window.AurixCloud?.remove(b.dataset.cloudRemove).then(()=>{toast('Cloud copy removed.','ok');render()}).catch(e=>toast(e.message,'err'));return}let id=b.dataset.fav||b.dataset.delete||b.dataset.copyItem||b.dataset.download||b.dataset.cloudSave,o=items.find(x=>x.id===id);if(!o)return;if(b.dataset.cloudSave){window.AurixCloud?.save(o).then(()=>toast('Saved to your cloud account.','ok')).catch(e=>toast(e.message,'err'));return}if(b.dataset.fav)toggleFav(id);else if(b.dataset.delete){if(confirm('Remove this saved item?'))delItem(id)}else if(b.dataset.copyItem)navigator.clipboard.writeText(o.result).then(()=>toast('Copied.','ok')).catch(()=>toast('Clipboard unavailable.','err'));else if(b.dataset.download)downloadImg(o)});
